class Solution:
    def minIncrease(self, n: int, edges: List[List[int]], cost: List[int]) -> int:
        g = [[] for _ in range(n)]
        for u, v in edges:
            g[u].append(v); g[v].append(u)
        par = [-1] * n
        order = [0]
        par[0] = -2
        qi = 0
        while qi < len(order):
            u = order[qi]; qi += 1
            for w in g[u]:
                if par[w] == -1:
                    par[w] = u
                    order.append(w)
        cbest = [0] * n
        cmax = [0] * n
        ccnt = [0] * n
        extra = [0] * n
        for u in reversed(order):
            v = cost[u] + cbest[u]
            if u != 0:
                p = par[u]
                if ccnt[p] == 0 or v > cmax[p]:
                    extra[p] += ccnt[p]
                    cmax[p] = v
                elif v < cmax[p]:
                    extra[p] += 1
                ccnt[p] += 1
                cbest[p] = max(cbest[p], v)
        return sum(extra)

