class Solution {
public:
    int minIncrease(int n, vector<vector<int>>& edges, vector<int>& cost) {
        vector<vector<int>> g(n);
        for (auto& e : edges) { g[e[0]].push_back(e[1]); g[e[1]].push_back(e[0]); }
        vector<int> par(n, -1), order;
        order.push_back(0); par[0] = -2;
        for (size_t qi = 0; qi < order.size(); qi++) {
            int u = order[qi];
            for (int w : g[u]) if (par[w] == -1) { par[w] = u; order.push_back(w); }
        }
        vector<long long> cbest(n, 0), cmax(n, 0);
        vector<int> ccnt(n, 0), extra(n, 0);
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            long long v = cost[u] + cbest[u];
            if (u != 0) {
                int p = par[u];
                if (ccnt[p] == 0 || v > cmax[p]) { extra[p] += ccnt[p]; cmax[p] = v; }
                else if (v < cmax[p]) extra[p] += 1;
                ccnt[p]++;
                cbest[p] = max(cbest[p], v);
            }
        }
        return accumulate(extra.begin(), extra.end(), 0);
    }
};

