class Solution {
    public int minIncrease(int n, int[][] edges, int[] cost) {
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        int[] par = new int[n]; Arrays.fill(par, -1);
        List<Integer> order = new ArrayList<>();
        order.add(0); par[0] = -2;
        for (int qi = 0; qi < order.size(); qi++) {
            int u = order.get(qi);
            for (int w : g.get(u)) if (par[w] == -1) { par[w] = u; order.add(w); }
        }
        long[] cbest = new long[n], cmax = new long[n];
        int[] ccnt = new int[n], extra = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            int u = order.get(i);
            long v = cost[u] + cbest[u];
            if (u != 0) {
                int p = par[u];
                if (ccnt[p] == 0 || v > cmax[p]) { extra[p] += ccnt[p]; cmax[p] = v; }
                else if (v < cmax[p]) extra[p] += 1;
                ccnt[p]++;
                cbest[p] = Math.max(cbest[p], v);
            }
        }
        int ans = 0;
        for (int x : extra) ans += x;
        return ans;
    }
}

