var minIncrease = function(n, edges, cost) {
    const g = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { g[u].push(v); g[v].push(u); }
    const par = new Array(n).fill(-1);
    const order = [0]; par[0] = -2;
    for (let qi = 0; qi < order.length; qi++) {
        const u = order[qi];
        for (const w of g[u]) if (par[w] === -1) { par[w] = u; order.push(w); }
    }
    const cbest = new Array(n).fill(0), cmax = new Array(n).fill(0);
    const ccnt = new Array(n).fill(0), extra = new Array(n).fill(0);
    for (let i = n - 1; i >= 0; i--) {
        const u = order[i], v = cost[u] + cbest[u];
        if (u !== 0) {
            const p = par[u];
            if (ccnt[p] === 0 || v > cmax[p]) { extra[p] += ccnt[p]; cmax[p] = v; }
            else if (v < cmax[p]) extra[p] += 1;
            ccnt[p]++;
            cbest[p] = Math.max(cbest[p], v);
        }
    }
    return extra.reduce((a, b) => a + b, 0);
};
